#include <DHT.h>

// =====================================
// KONFIGURACJA
// =====================================

#define DHTPIN 12
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

// =====================================
// ZMIENNE
// =====================================

int liczba = 0;

int minimum, maksimum;
int jasnosc = 0;
int wilgotnosc = 0;
int temperatura = 0;

char tryb = 'L';

unsigned long czasPomiaru = 0;
unsigned long czasOdswiezania = 0;

// Obsluga przycisku
bool ostatniOdczyt = HIGH;
bool stabilnyStan = HIGH;
unsigned long czasZmiany = 0;

// =====================================
// TABLICA CYFR - WSPOLNA ANODA
// Kolejnosc bitow: A B C D E F G
// 0 = segment swieci
// =====================================

const byte cyfry[10] = {
  0b0000001, // 0
  0b1001111, // 1
  0b0010010, // 2
  0b0000110, // 3
  0b1001100, // 4
  0b0100100, // 5
  0b0100000, // 6
  0b0001111, // 7
  0b0000000, // 8
  0b0000100  // 9
};

// =====================================
// STEROWANIE SEGMENTAMI
// =====================================

void Znak(int numer) {

  numer = constrain(numer, 0, 9);

  byte wzor = cyfry[numer];

  // D2-D7: segmenty A-F
  byte portD = ((wzor >> 1) & 0b00111111) << 2;

  // D8: segment G
  byte portB = wzor & 1;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB) {
    PORTB |= 0b00000001;
  } else {
    PORTB &= 0b11111110;
  }
}

// =====================================
// WYSWIETLANIE DWÓCH CYFR
// =====================================

void Wyswietl() {

  // Wylacz obie cyfry
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  // Dziesiatki
  Znak(liczba / 10);

  digitalWrite(10, HIGH);
  delayMicroseconds(2000);
  digitalWrite(10, LOW);

  // Jednosci
  Znak(liczba % 10);

  digitalWrite(11, HIGH);
  delayMicroseconds(2000);
  digitalWrite(11, LOW);
}

// =====================================
// WYBOR WYSWIETLANEJ WARTOSCI
// =====================================

void WybierzTryb() {

  switch (tryb) {

    case 'L':
      liczba = jasnosc;
      break;

    case 'H':
      liczba = wilgotnosc;
      break;

    case 'T':
      liczba = temperatura;
      break;
  }

  liczba = constrain(liczba, 0, 99);
}

// =====================================
// ODCZYT CZUJNIKOW
// =====================================

void Pomiar() {

  // Odczyt jasnosci
  int odczyt = analogRead(A0);

  if (odczyt < minimum) minimum = odczyt;
  if (odczyt > maksimum) maksimum = odczyt;

  if (maksimum > minimum) {
    jasnosc = map(odczyt, minimum, maksimum, 0, 99);
  }

  jasnosc = constrain(jasnosc, 0, 99);

  // Odczyt DHT11
  float h = dht.readHumidity();
  float t = dht.readTemperature();

  // Sprawdzenie poprawnosci danych
  if (!isnan(h) && !isnan(t)) {

    wilgotnosc = constrain((int)(h + 0.5), 0, 99);

    temperatura = (int)(t + 0.5);
    temperatura = constrain(temperatura, 0, 99);

  } else {

    Serial.println("BLAD ODCZYTU DHT11");
  }

  // Aktualizacja wyswietlanej wartosci
  WybierzTryb();

  // Dane diagnostyczne
  Serial.print("L: ");
  Serial.print(jasnosc);

  Serial.print(" % | H: ");
  Serial.print(wilgotnosc);

  Serial.print(" % | T: ");
  Serial.print(temperatura);

  Serial.println(" C");
}

// =====================================
// OBSLUGA PRZYCISKU
// =====================================

void Przycisk() {

  bool odczyt = digitalRead(9);

  if (odczyt != ostatniOdczyt) {

    ostatniOdczyt = odczyt;
    czasZmiany = millis();
  }

  if (millis() - czasZmiany >= 40) {

    if (odczyt != stabilnyStan) {

      stabilnyStan = odczyt;

      if (stabilnyStan == LOW) {

        if (tryb == 'L') {
          tryb = 'H';
        }
        else if (tryb == 'H') {
          tryb = 'T';
        }
        else {
          tryb = 'L';
        }

        WybierzTryb();

        Serial.print("AKTYWNY TRYB: ");
        Serial.println(tryb);
      }
    }
  }
}

// =====================================
// SETUP
// =====================================

void setup() {

  Serial.begin(9600);

  // Segmenty D2-D7
  DDRD |= 0b11111100;

  // D8, D10, D11
  DDRB |= 0b00001101;

  // Przycisk
  pinMode(9, INPUT_PULLUP);

  // DHT11
  dht.begin();

  // Wylaczenie wyswietlaczy
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  delay(2000);

  // Kalibracja jasnosci
  minimum = analogRead(A0);
  maksimum = minimum;

  Pomiar();

  czasPomiaru = millis();
  czasOdswiezania = micros();
}

// =====================================
// LOOP
// =====================================

void loop() {

  // Odswiezanie wyswietlacza
  if (micros() - czasOdswiezania >= 4000) {

    czasOdswiezania = micros();

    Wyswietl();
  }

  // Obsluga przycisku
  Przycisk();

  // Pomiar co 2 sekundy
  if (millis() - czasPomiaru >= 2000) {

    czasPomiaru = millis();

    Pomiar();
  }
}

